    def test_has_blocked_evidence(self):from smr_phase82_multi_ticker_metric_loader import load_multi_ticker_metrics;from smr_phase82_multi_ticker_time_series_builder import build_time_series;from smr_phase82_multi_ticker_baseline_builder import build_multi_baselines;from smr_phase82_multi_ticker_delta_detector import detect_multi_delta;from smr_phase82_multi_ticker_threshold_engine import run_multi_threshold;from smr_phase82_multi_ticker_monitoring_evidence import build_multi_monitoring_evidence;m=load_multi_ticker_metrics();s=build_time_series(m);b=build_multi_baselines(s);d=detect_multi_delta(b);t=run_multi_threshold(d);r=build_multi_monitoring_evidence(d,t);rows=r["phase82_multi_ticker_monitoring_evidence"]["rows"];self.assertTrue(any(row["evidence_type"]=="structured_data_unavailable_observed" for row in rows))
